package android.net.nsd;import java.util.*;public class NsdManager {public static final int PROTOCOL_DNS_SD=1;public int port=37599;public boolean advertise=true,holdResolve;public final List<DiscoveryListener> active=new ArrayList<>();public final List<Runnable> held=new ArrayList<>();public interface DiscoveryListener {void onDiscoveryStarted(String t);void onDiscoveryStopped(String t);void onServiceFound(NsdServiceInfo info);void onServiceLost(NsdServiceInfo info);void onStartDiscoveryFailed(String t,int c);void onStopDiscoveryFailed(String t,int c);}public interface ResolveListener {void onResolveFailed(NsdServiceInfo i,int c);void onServiceResolved(NsdServiceInfo i);}public void discoverServices(String type,int protocol,DiscoveryListener listener){active.add(listener);listener.onDiscoveryStarted(type);if(advertise){NsdServiceInfo info=new NsdServiceInfo(type);info.port=port;listener.onServiceFound(info);}}public void stopServiceDiscovery(DiscoveryListener listener){active.remove(listener);listener.onDiscoveryStopped("");}public void resolveService(NsdServiceInfo info,ResolveListener listener){Runnable resolve=()->listener.onServiceResolved(info);if(holdResolve)held.add(resolve);else resolve.run();}}
